using System;using System.Collections.Generic;public class Solution{public IList<IList<int>> GetSkyline(int[][]b){var e=new List<(int x,int h)>();foreach(var v in b){e.Add((v[0],-v[2]));e.Add((v[1],v[2]));}e.Sort((a,c)=>a.x!=c.x?a.x.CompareTo(c.x):a.h.CompareTo(c.h));var h=new SortedDictionary<int,int>{{0,1}};var o=new List<IList<int>>();int prev=0;foreach(var v in e){if(v.h<0){int z=-v.h;h[z]=h.GetValueOrDefault(z)+1;}else{h[v.h]--;if(h[v.h]==0)h.Remove(v.h);}int cur=0;foreach(var k in h.Keys)cur=k;if(cur!=prev){o.Add(new List<int>{v.x,cur});prev=cur;}}return o;}}
